<script setup lang="ts">
import { Heart, Info, Minus, Plus, ShieldCheck, ShoppingBasket, Truck } from '@lucide/vue'
import type { StoreProduct, StorefrontPayload } from '#shared/types/storefront'
import { useStorefrontCatalog } from '~~/layers/storefront-core/app/composables/useStorefrontCatalog'
import { useStorefrontCommerce } from '~~/layers/storefront-core/app/composables/useStorefrontCommerce'
const props = defineProps<{ product: StoreProduct, storefront: StorefrontPayload }>()
const quantity = ref(1)
const { money, productImage, usePlaceholder, discount } = useStorefrontCatalog(props.storefront)
const { addToCart, toggleWishlist, isWishlisted, busyProducts } = useStorefrontCommerce(props.storefront)
const wished = computed(() => isWishlisted(props.product.id))
const busy = computed(() => busyProducts.value.includes(props.product.id))
</script>

<template>
  <main class="detail-page"><nav class="breadcrumbs text-sm" aria-label="Navegação estrutural"><ul><li><NuxtLink to="/">Início</NuxtLink></li><li><NuxtLink to="/produtos">Produtos</NuxtLink></li><li class="truncate">{{ product.name }}</li></ul></nav><div class="detail-grid"><div class="product-image"><img v-if="productImage(product)" :src="productImage(product)!" :alt="product.name" @error="usePlaceholder"><img v-else src="/images/placeholders/product-default.png" alt="Imagem ilustrativa do produto"><span v-if="discount(product)" class="detail-discount badge badge-secondary">{{ discount(product) }}% de desconto</span><span class="image-cross" aria-hidden="true">+</span></div><section class="product-info"><span class="category">{{ product.categories[0]?.name || 'Cuidado diário' }}</span><h1>{{ product.name }}</h1><p class="sku">Cód. {{ product.sku }} · <span class="badge badge-sm" :class="product.stock>0?'badge-success badge-outline':'badge-error badge-outline'">{{ product.stock > 0 ? 'Em estoque' : 'Indisponível' }}</span></p><div class="price"><s v-if="product.original_price && product.original_price > product.price">{{ money(product.original_price) }}</s><strong>{{ money(product.price) }}</strong><span>à vista</span></div><p class="description">{{ product.description || product.excerpt || 'Produto selecionado para tornar o cuidado diário mais simples e confiável.' }}</p><div class="buy-row"><div class="join"><button class="btn join-item" type="button" aria-label="Diminuir quantidade" @click="quantity=Math.max(1,quantity-1)"><Minus :size="15"/></button><span class="btn join-item pointer-events-none">{{ quantity }}</span><button class="btn join-item" type="button" aria-label="Aumentar quantidade" @click="quantity=Math.min(product.stock,quantity+1)"><Plus :size="15"/></button></div><button class="add btn btn-primary" type="button" :disabled="product.stock<1 || busy" @click="addToCart(product,quantity)"><span v-if="busy" class="loading loading-spinner loading-sm"></span><ShoppingBasket v-else :size="19"/>{{ product.stock<1?'Produto indisponível':'Adicionar à cesta' }}</button><button class="wish btn btn-square" :class="wished?'btn-secondary':'btn-outline'" type="button" :aria-label="wished?'Remover da lista de desejos':'Adicionar à lista de desejos'" :aria-pressed="wished" @click="toggleWishlist(product)"><Heart :size="19" :fill="wished?'currentColor':'none'"/></button></div><small class="integration">Compre como visitante. Você só informa seus dados ao finalizar.</small><div class="benefits"><div><Truck :size="21"/><span><strong>Entrega para sua região</strong><small>Informe o CEP no carrinho</small></span></div><div><ShieldCheck :size="21"/><span><strong>Compra protegida</strong><small>Seus dados em segurança</small></span></div></div><div class="notice alert alert-info"><Info :size="19"/><p><strong>Cuide-se com informação.</strong><span>Leia as orientações do produto. Em caso de dúvida, procure um profissional de saúde.</span></p></div></section></div></main>
</template>

